const principal = (userId: any, orgId: any) => ({ userId, email: "x@y.z", activeOrgId: orgId, expiresAt: new Date(Date.now() + 1e6).toISOString() as any });

describe("former members", () => {
  it("full lifecycle", async () => {
    const t = await createTenant("life", "growth");
    const other = await createTenant("other", "growth");
