    await usageRepo.recomputeUsage(t.org.id);
    const target = (await memberRepo.findMember(t.org.id, t.userIds.member))!;
    const sessionPrincipal = principal(t.userIds.member, t.org.id);
    expect(await sessionService.resolveActorForOrg(sessionPrincipal, t.org.slug)).not.toBeNull();
    const seen = (await memberRepo.findMember(t.org.id, t.userIds.member))!;
    expect(seen.lastSeenAt).not.toBeNull();

