    const led = await projectService.createProject(t.actors.admin, { orgId: t.org.id, name: "Led", slug: "led", key: "LED", description: null, visibility: "org", leadId: t.userIds.member, color: "#6366f1", targetDate: null });
    await preferenceRepo.upsertPreference({ orgId: t.org.id, userId: t.userIds.member, kind: "issue_assigned", inApp: true, email: true, digestOnly: true });
    expect(await listDigestRecipients(t.org.id)).toEqual([t.userIds.member]);

    const before = await usageRepo.getUsage(t.org.id);
    const removed = await memberService.removeMember(t.actors.admin, { orgId: t.org.id, memberId: target.id });
    expect(removed.archivedAt).not.toBeNull();
    const after = await usageRepo.getUsage(t.org.id);
    expect(after.seatsUsed).toBe(before.seatsUsed - 1);

    // sessions
    expect(await sessionService.resolveActorForOrg(sessionPrincipal, t.org.slug)).toBeNull();
    expect(await memberService.resolveActor(t.userIds.member, t.org.id)).toBeNull();
    await expect(sessionService.switchActiveOrg(sessionPrincipal, { orgId: t.org.id })).rejects.toThrow();
    expect(await sessionService.resolveActorForOrg(sessionPrincipal, other.org.slug)).not.toBeNull();
    expect((await orgRepo.listOrgsForUser(t.userIds.member)).map((o) => o.id)).toEqual([other.org.id]);

    // cascade
    expect((await issueRepo.findIssueById(t.org.id, assigned.id))!.assigneeId).toBeNull();
    expect((await projectRepo.findProjectById(t.org.id, led.id))!.leadId).toBeNull();

    // conflicts
    const roleErr = await memberService.updateMemberRole(t.actors.admin, { orgId: t.org.id, memberId: target.id, role: "viewer" }).catch((e) => e);
    expect(roleErr).toBeInstanceOf(AlreadyArchivedError);
    expect(toAppError(roleErr).code).toBe("conflict");
    await expect(memberService.removeMember(t.actors.admin, { orgId: t.org.id, memberId: target.id })).rejects.toBeInstanceOf(AlreadyArchivedError);
    expect((await usageRepo.getUsage(t.org.id)).seatsUsed).toBe(after.seatsUsed);
    const audit = await activityRepo.listActivity({ orgId: t.org.id, limit: 100, cursor: null } as any);
    expect(audit.items.filter((a) => a.action === "member.role_changed")).toHaveLength(0);

    // assignment / lead refused
    const issueCount = await issueRepo.countIssues(t.org.id, t.project.id);
    await expect(issueService.createIssue(t.actors.admin, issueInput(t.org.id, t.project.id, { assigneeId: t.userIds.member }))).rejects.toThrow(/not a current member/);
    expect(await issueRepo.countIssues(t.org.id, t.project.id)).toBe(issueCount);
    await expect(issueService.assignIssue(t.actors.admin, { orgId: t.org.id, issueId: assigned.id, assigneeId: t.userIds.member })).rejects.toThrow();
    await expect(issueService.assignIssue(t.actors.admin, { orgId: t.org.id, issueId: assigned.id, assigneeId: other.userIds.admin })).rejects.toThrow();
    const projCount = await projectRepo.countProjects(t.org.id);
    await expect(projectService.createProject(t.actors.admin, { orgId: t.org.id, name: "Nope", slug: "nope", key: "NOP", description: null, visibility: "org", leadId: t.userIds.member, color: "#6366f1", targetDate: null })).rejects.toThrow();
    expect(await projectRepo.countProjects(t.org.id)).toBe(projCount);
    await expect(projectService.updateProject(t.actors.admin, { orgId: t.org.id, projectId: led.id, name: "Renamed", leadId: t.userIds.member })).rejects.toThrow();
    expect((await projectRepo.findProjectById(t.org.id, led.id))!.name).toBe("Led");

    // notifications
    const listFor = async () => (await listNotifications(t.actors.owner, { orgId: t.org.id, recipientId: t.userIds.member, unreadOnly: false, limit: 50, cursor: null } as any)).total;
    const n0 = await listFor();
    await commentService.createComment(t.actors.admin, { orgId: t.org.id, issueId: authored.id, body: "hello @member", parentId: null, mentionedUserIds: [t.userIds.member] } as any);
    await issueRepo.setIssueAssignee(t.org.id, assigned.id, t.userIds.member); // legacy row
    await runOverdueIssueJob(new Date());
    expect(await notify(t.org.id, "member_joined", [t.userIds.member], { title: "t", body: "b", href: "/", actorId: null })).toHaveLength(0);
    expect(await listFor()).toBe(n0);
    expect(await listDigestRecipients(t.org.id)).toEqual([]);
    expect(await preferenceRepo.listDigestSubscribers(t.org.id)).toEqual([]);

    // legacy repair
    await runMigrations(process.env.TASKFLOW_DB_PATH!);
    expect((await issueRepo.findIssueById(t.org.id, assigned.id))!.assigneeId).toBeNull();
    expect((await projectRepo.findProjectById(t.org.id, t.project.id))!.leadId).toBe(t.userIds.owner);

    // re-invite
    const token = "r".repeat(32);
    const inv = await invitationRepo.insertInvitation(t.org.id, { orgId: t.org.id, email: "member@life.test", role: "admin", expiresInDays: 14 }, t.userIds.owner, hashToken(token));
    const joined: any[] = [];
    const off = subscribe("member.joined", (p) => { joined.push(p); });
    const seatsBefore = (await usageRepo.getUsage(t.org.id)).seatsUsed;
    const back = await invitationService.acceptInvitation(t.userIds.member, { token });
    off();
    const invAfter = (await invitationRepo.findInvitationByTokenHash(hashToken(token)))!;
    expect(back).toMatchObject({ id: target.id, role: "admin", status: "active", archivedAt: null, invitedBy: t.userIds.owner, joinedAt: invAfter.acceptedAt, createdAt: target.createdAt, lastSeenAt: seen.lastSeenAt });
    expect(joined).toHaveLength(1);
    expect((await usageRepo.getUsage(t.org.id)).seatsUsed).toBe(seatsBefore + 1);
    expect(await memberRepo.countActiveMembers(t.org.id)).toBe(4);
    const page = await memberRepo.listMembers({ orgId: t.org.id, limit: 50, cursor: null });
    expect(page.items.filter((m) => m.userId === t.userIds.member)).toHaveLength(1);
    expect(await sessionService.resolveActorForOrg(sessionPrincipal, t.org.slug)).toMatchObject({ role: "admin" });
    expect((await orgRepo.listOrgsForUser(t.userIds.member)).length).toBe(2);
    await expect(invitationService.acceptInvitation(t.userIds.member, { token })).rejects.toThrow(/already been accepted/);
    expect(await notify(t.org.id, "member_joined", [t.userIds.member], { title: "t", body: "b", href: "/", actorId: null })).toHaveLength(1);
    expect(await listDigestRecipients(t.org.id)).toEqual([t.userIds.member]);

    // current member accepts another invite: nothing changes, invite consumed
    const token2 = "s".repeat(32);
    await invitationRepo.insertInvitation(t.org.id, { orgId: t.org.id, email: "viewer@life.test", role: "admin", expiresInDays: 14 }, t.userIds.owner, hashToken(token2));
    const viewerBefore = await memberRepo.findMember(t.org.id, t.userIds.viewer);
    const seats2 = (await usageRepo.getUsage(t.org.id)).seatsUsed;
    const same = await invitationService.acceptInvitation(t.userIds.viewer, { token: token2 });
    expect(same).toEqual(viewerBefore);
    expect((await usageRepo.getUsage(t.org.id)).seatsUsed).toBe(seats2);
    expect((await invitationRepo.findInvitationByTokenHash(hashToken(token2)))!.acceptedAt).not.toBeNull();
    await expect(invitationService.acceptInvitation(t.userIds.owner, { token: token2 })).rejects.toThrow(/already been accepted/);
    expect(await invitationRepo.countPendingInvitations(t.org.id)).toBe(0);
    void inv; void emit;
  });
});
