 * An invitation is used up by being accepted, whoever accepts it, and what it
 * does to the membership depends on what the workspace already knows:
 *
 *  - a stranger gets a new membership;
 *  - a former member (removed earlier) is re-admitted on the row they already
 *    have — (org, user) is unique, so there is never a second one — with the
 *    invitation's role and inviter and the acceptance time as the join date;
 *  - a current member is left exactly as they are: no role change, no seat.
 */
export async function acceptInvitation(
  userId: UserId,
  input: AcceptInvitationTokenInput,
): Promise<Member> {
  const invitation = requireFound(
    await invitationRepo.findInvitationByTokenHash(hashToken(input.token)),
    "Invitation",
    "token",
  );

  if (invitation.revokedAt !== null) {
    throw new Error("That invitation has been revoked");
  }
  if (invitation.acceptedAt !== null) {
    throw new Error("That invitation has already been accepted");
  }
  if (invitation.expiresAt <= toIsoTimestamp(new Date())) {
    throw new Error("That invitation has expired");
  }

  const acceptedAt = toIsoTimestamp(new Date());
  const existing = await memberRepo.findMember(invitation.orgId, userId);

  // Spent first, so the token cannot be replayed whatever happens next.
  await invitationRepo.markInvitationAccepted(
    invitation.orgId,
    invitation.id,
    acceptedAt,
  );

  if (existing !== null && isReadmissionBlocked(existing)) return existing;

  const member =
    existing === null
      ? await memberRepo.insertMember(
          invitation.orgId,
          userId,
          invitation.role,
          invitation.invitedBy,
          acceptedAt,
        )
      : await memberRepo.reactivateMember(
          invitation.orgId,
          existing.id,
          invitation.role,
          invitation.invitedBy,
          acceptedAt,
        );

  await emit("member.joined", {
    ...envelope(invitation.orgId, userId),
    memberId: member.id,
    userId,
    role: member.role,
  });

  return member;
}

